/**
 * The row's one verdict. A combined bound speaks for all models; a provider
 * without one (Copilot - window relationships unknown) gets the lowest READ
 * window's own runway and never an all-models claim; a stale row says its
 * age and derives nothing (providerScopes already returns nothing for it).
 */
function verdictFor(kind: RowKind, row: QuotaProviderView | undefined, now: number) {
  if (kind === "paused") return { text: "paused", tone: "neutral" } as Verdict;
  if (kind === "stale" && row) {
    return {
      text: row.measuredAt !== undefined ? measuredAgeText(row.measuredAt, now) : "stale",
      tone: "warn",
    } as Verdict;
  }
  if (kind !== "ok" || !row) return undefined;
  const headline = providerScopes(row, now).allModels;
  if (headline && typeof headline.effectivePercentRemaining === "number") {
    return runwayVerdict(headline.runway, now, true);
  }
  const read = row.windows.filter((window) => typeof window.percentRemaining === "number");
  if (read.length === 0) return undefined;
  const lowest = read.reduce((a, b) =>
    (b.percentRemaining as number) < (a.percentRemaining as number) ? b : a,
  );
  const signals = windowSignals(lowest, now);
  if (signals.kind !== "measured") return undefined;
  return runwayVerdict(
    signals.projectedExhaustedAtMs !== undefined
      ? { status: "projected_exhaustion", projectedExhaustedAtMs: signals.projectedExhaustedAtMs }
      : { status: "through_reset" },
    now,
    false,
