describe("PushedQuotaStore", () => {
  it("keeps the latest reading per window and survives a restart", () => {
    const db = openInMemoryDatabase();
    const store = new PushedQuotaStore(db);
    store.record("acct_a", {
      windowId: "five_hour",
      utilization: 0.3,
      resetsAt: NOW + 1000,
      at: NOW,
    });
    store.record("acct_a", {
      windowId: "five_hour",
      utilization: 0.8,
      resetsAt: NOW + 2000,
      at: NOW + 60,
    });
    store.record("acct_a", { windowId: "seven_day", utilization: 0.1, at: NOW });

    const reopened = new PushedQuotaStore(db);
    const windows = reopened
      .windowsFor("acct_a")
      .sort((a, b) => a.windowId.localeCompare(b.windowId));
    expect(windows).toEqual([
      { windowId: "five_hour", utilization: 0.8, resetsAt: NOW + 2000, at: NOW + 60 },
      { windowId: "seven_day", utilization: 0.1, at: NOW },
    ]);
  });

  it("never lets one account's reading colour a sibling's", () => {
    const store = new PushedQuotaStore(openInMemoryDatabase());
    store.record("acct_a", { windowId: "five_hour", utilization: 1, at: NOW });

    expect(store.windowsFor("acct_b")).toEqual([]);
    store.forget("acct_a");
    expect(store.windowsFor("acct_a")).toEqual([]);
  });
});

